"use client";

import { CaseStudyCard as CaseStudyCardComponent } from "../case-studies/case-study-card";

type CaseItem = {
  tag: { en: string; no: string };
  tags?: Array<{ en: string; no: string }>;
  industry: { en: string; no: string };
  previewMode?: "image" | "before-after";
  showHeader?: boolean;
  challenge: { en: string; no: string };
  result: { en: string; no: string };
  metric: string;
  metricLabel: { en: string; no: string };
  insightTabs?: Array<{
    id: string;
    title: { en: string; no: string };
    highlights: Array<{ en: string; no: string }>;
    microcopy?: { en: string; no: string };
  }>;
  imageLabel?: { en: string; no: string };
  ctaLabel?: { en: string; no: string };
  image?: string;
  imageAlt?: string;
  href?: string;
};

function pick(locale: "en" | "no", v: { en: string; no: string }): string {
  return locale === "no" ? v.no : v.en;
}

// Placeholder image URLs - in production, these would be real case images
const caseImageMap: Record<string, string> = {
  "Norwegian Food Platform": "/images/recipeseo.png",
  "Leading Norwegian Interior Brand": "/images/gardinguide.png",
  "B2B SaaS": "/images/melk-website.png",
  "Professional Services": "/images/gardinguide.png",
  "Nordic Ecommerce": "/images/fjord1.png",
  "International Travel Platform": "/images/travelseo.png",
  "Food & Nutrition": "/images/melk-website.png",
  "Tekstil": "/images/gardinguide.png",
};

const caseImageAltMap: Record<string, string> = {
  "Norwegian Food Platform": "Anonymized food platform recipe and UX preview",
  "Leading Norwegian Interior Brand": "Anonymized interior and curtain guidance preview",
  "B2B SaaS": "B2B SaaS case study illustration",
  "Professional Services": "Professional services case study illustration",
  "Nordic Ecommerce": "E-commerce case study illustration",
  "International Travel Platform": "Anonymized international travel content ecosystem preview",
  "Food & Nutrition": "Food and nutrition case study illustration",
  "Tekstil": "Princess gardiner case study illustration",
};

export function CaseStudyCard({
  item,
  locale,
  index,
}: {
  item: CaseItem;
  locale: "en" | "no";
  index: number;
}) {
  const industryKey = item.industry.en;
  const imageUrl = caseImageMap[industryKey] || `/images/case-${index + 1}.jpg`;
  const imageAlt = caseImageAltMap[industryKey] || `Case study ${index + 1}`;
  const cardTags = item.tags?.map((tag) => pick(locale, tag)) || [pick(locale, item.industry)];
  const insightTabs = item.insightTabs?.map((tab) => ({
    id: tab.id,
    title: pick(locale, tab.title),
    highlights: tab.highlights.map((highlight) => pick(locale, highlight)),
    microcopy: tab.microcopy ? pick(locale, tab.microcopy) : undefined,
  }));

  return (
    <CaseStudyCardComponent
      id={`case-${index}`}
      image={imageUrl}
      imageAlt={imageAlt}
      imageLabel={item.imageLabel ? pick(locale, item.imageLabel) : undefined}
      previewMode={item.previewMode}
      showHeader={item.showHeader}
      title={pick(locale, item.result)}
      summary={pick(locale, item.challenge)}
      result={item.metric}
      resultLabel={pick(locale, item.metricLabel)}
      category={pick(locale, item.tag)}
      tags={cardTags}
      insightTabs={insightTabs}
      ctaLabel={
        item.ctaLabel
          ? pick(locale, item.ctaLabel)
          : pick(locale, { en: "Discuss your needs", no: "Diskuter dine behov" })
      }
      ctaHref={item.href}
    />
  );
}
